using System.Diagnostics;using Avalonia;using Avalonia.Controls;using Avalonia.Layout;using Avalonia.Media;using Accyourate.App.AssetManagement.Services;using Accyourate.App.UIFramework.Tokens;
namespace Accyourate.App.AssetManagement;
public sealed class SupplierRmaCapaGovernanceActionAnalyticsWindow:Window
{
 private readonly SupplierRmaCapaGovernanceActionService _actions=new();private readonly SupplierRmaCapaGovernanceActionAnalyticsService _analytics=new();private readonly StackPanel _content=new();private readonly TextBlock _message=new();private readonly ComboBox _period=new(){ItemsSource=new[]{"Tutto il periodo","Ultimi 30 giorni","Ultimi 90 giorni","Anno corrente"},SelectedIndex=0,MinWidth=170},_source=new(){MinWidth=170},_owner=new(){MinWidth=200};private IReadOnlyList<SupplierRmaCapaGovernanceAction> _filtered=Array.Empty<SupplierRmaCapaGovernanceAction>();
 public SupplierRmaCapaGovernanceActionAnalyticsWindow(){Title="Indicatori Piano azioni CAPA";Width=1250;Height=780;WindowStartupLocation=WindowStartupLocation.CenterOwner;var all=_actions.GetAll();_source.ItemsSource=new[]{"Tutte le origini"}.Concat(all.Select(x=>x.SourceType).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct().OrderBy(x=>x)).ToArray();_owner.ItemsSource=new[]{"Tutti i responsabili"}.Concat(all.Select(x=>x.Owner).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct().OrderBy(x=>x)).ToArray();_source.SelectedIndex=0;_owner.SelectedIndex=0;Content=Build();_period.SelectionChanged+=(_,_)=>Load();_source.SelectionChanged+=(_,_)=>Load();_owner.SelectionChanged+=(_,_)=>Load();Load();}
 private Control Build(){var root=new DockPanel{Margin=new Thickness(24)};var head=new Grid{ColumnDefinitions=new ColumnDefinitions("*,Auto"),Margin=new Thickness(0,0,0,12)};Add(head,new StackPanel{Children={new TextBlock{Text="Indicatori Piano azioni CAPA",FontSize=28,FontWeight=FontWeight.Bold},new TextBlock{Text="Avanzamento, puntualita, priorita e carichi per responsabile.",Foreground=UiTokens.Brush(UiTokens.TextSecondary)}}},0);var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=8};actions.Children.Add(SupplierRmaCorrectiveActionsWindow.Button("Esporta CSV",()=>Export(false)));actions.Children.Add(SupplierRmaCorrectiveActionsWindow.Button("Report PDF",()=>Export(true),true));Add(head,actions,1);DockPanel.SetDock(head,Dock.Top);root.Children.Add(head);var filters=new Grid{ColumnDefinitions=new ColumnDefinitions("170,170,200,*"),Margin=new Thickness(0,0,0,10)};Add(filters,_period,0);Add(filters,_source,1);Add(filters,_owner,2);DockPanel.SetDock(filters,Dock.Top);root.Children.Add(filters);DockPanel.SetDock(_message,Dock.Top);root.Children.Add(_message);root.Children.Add(new ScrollViewer{Content=_content});return root;}
 private void Load(){var all=_actions.GetAll();var from=_period.SelectedItem?.ToString() switch{"Ultimi 30 giorni"=>DateTime.Today.AddDays(-30),"Ultimi 90 giorni"=>DateTime.Today.AddDays(-90),"Anno corrente"=>new DateTime(DateTime.Today.Year,1,1),_=>DateTime.MinValue};var source=_source.SelectedItem?.ToString()??"Tutte le origini";var owner=_owner.SelectedItem?.ToString()??"Tutti i responsabili";_filtered=all.Where(x=>!DateTime.TryParse(x.CreatedAt,out var d)||d>=from).Where(x=>source=="Tutte le origini"||x.SourceType==source).Where(x=>owner=="Tutti i responsabili"||x.Owner==owner).ToList();var a=_analytics.Analyze(_filtered);_content.Children.Clear();_content.Spacing=14;var cards=new WrapPanel();cards.Children.Add(Card("Totali",a.Total,UiTokens.BrandBlue));cards.Children.Add(Card("Aperte",a.Open,UiTokens.Warning));cards.Children.Add(Card("In corso",a.InProgress,UiTokens.BrandBlue));cards.Children.Add(Card("Completate",a.Completed,UiTokens.Success));cards.Children.Add(Card("Scadute",a.Overdue,UiTokens.Danger));cards.Children.Add(Card("Tempo medio",$"{a.AverageCompletionDays:N1} gg",UiTokens.BrandBlue));cards.Children.Add(Card("Entro scadenza",$"{a.OnTimePercentage:N1}%",a.OnTimePercentage>=80?UiTokens.Success:UiTokens.Warning));_content.Children.Add(cards);_content.Children.Add(Breakdown("Distribuzione per priorita",a.ByPriority));_content.Children.Add(Breakdown("Carico per responsabile",a.ByOwner));_message.Text=$"{_filtered.Count} azioni incluse negli indicatori";_message.Foreground=UiTokens.Brush(UiTokens.TextSecondary);_message.Margin=new Thickness(0,0,0,10);}
 private void Export(bool pdf){try{var filter=$"Periodo: {_period.SelectedItem}; origine: {_source.SelectedItem}; responsabile: {_owner.SelectedItem}";var path=pdf?_analytics.ExportPdf(_filtered,filter):_analytics.ExportCsv(_filtered,filter);_message.Text=$"File creato: {Path.GetFileName(path)}";_message.Foreground=UiTokens.Brush(UiTokens.Success);Process.Start(new ProcessStartInfo{FileName=path,UseShellExecute=true});}catch(Exception ex){_message.Text=$"Errore esportazione: {ex.Message}";_message.Foreground=UiTokens.Brush(UiTokens.Danger);}}
 private static Control Card(string label,object value,string color)=>new Border{Width=200,Height=95,Margin=new Thickness(0,0,10,10),Padding=new Thickness(14),BorderBrush=UiTokens.Brush(UiTokens.Border),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Child=new StackPanel{Children={new TextBlock{Text=value.ToString(),FontSize=27,FontWeight=FontWeight.Bold,Foreground=UiTokens.Brush(color)},new TextBlock{Text=label}}}};private static Control Breakdown(string title,IReadOnlyDictionary<string,int> values){var root=new StackPanel{Spacing=5};root.Children.Add(new TextBlock{Text=title,FontSize=20,FontWeight=FontWeight.Bold});if(values.Count==0)root.Children.Add(new TextBlock{Text="Nessun dato disponibile.",Foreground=UiTokens.Brush(UiTokens.TextSecondary)});foreach(var x in values)root.Children.Add(new Border{Padding=new Thickness(10),BorderBrush=UiTokens.Brush(UiTokens.Border),BorderThickness=new Thickness(0,0,0,1),Child=new Grid{ColumnDefinitions=new ColumnDefinitions("*,100"),Children={new TextBlock{Text=x.Key},Value(x.Value)}}});return root;}private static TextBlock Value(int value){var t=new TextBlock{Text=value.ToString(),FontWeight=FontWeight.Bold,HorizontalAlignment=HorizontalAlignment.Right};Grid.SetColumn(t,1);return t;}private static void Add(Grid g,Control x,int c){x.Margin=new Thickness(0,0,8,0);Grid.SetColumn(x,c);g.Children.Add(x);}
}
